#include "rules/push_review_declaration.h"
#include <cstdlib>
#include <iostream>
using namespace billiardgl::rules;
namespace{class Auth:public RefereeAuthorityAuthenticator{bool verify(const RefereeAuthenticationInput&i)const override{return i.authenticationProof==refereeAuthoritySha256Hex(i.authenticatedBytes);}};void e(bool v,const char*m){if(!v){std::cerr<<m<<'\n';std::exit(1);}}void sign(RefereeAuthorityRequest&r){r.authenticationProof=refereeAuthoritySha256Hex(canonicalRefereeAuthenticatedBytes(r));}RefereeAuthorityRequest req(const PushReviewAuthority&a,RefereeAuthorityOperation op,std::string p,std::string k){RefereeAuthorityRequest r;r.protocolId=kRefereeAuthorityProtocolId;r.schemaVersion=1;r.operation=op;r.declarationKind=kPushReviewDeclarationKind;r.decisionId="push.1";r.rackIdentity=a.state().rackIdentity;r.expectedAuthorityRevision=a.protocolState().authorityRevision;r.expectedAuthorityStateHash=a.protocolState().authorityStateHash;r.authorityRole=RefereeAuthorityRole::Referee;r.authoritySubjectId="ref";r.credentialId="c";r.keyVersion="v";r.authenticationNonce="n"+k;r.expiresAtAuthorityTick=100;r.idempotencyKey=k;r.payloadCanonical=p;sign(r);return r;}void test(){Auth x;PushReviewAuthority a(&x);a.reset("rack");PushReviewContext c{0,1,"state"};std::string p="{\"cue_ball_id\":0,\"push_review_required\":true,\"relation\":\"POTENTIAL_OBVIOUS_PUSH_REQUIRES_COMPLETE_MEASUREMENTS_AND_REFEREE_REVIEW\"}";auto q=req(a,RefereeAuthorityOperation::Propose,p,"p");e(a.propose(q,c,1).ok&&!a.state().reviewNeeded,"proposal");std::string f="{\"cue_ball_id\":0,\"proposal_decision_id\":\"push.1\",\"push_review_required\":true,\"relation\":\"POTENTIAL_OBVIOUS_PUSH_REQUIRES_COMPLETE_MEASUREMENTS_AND_REFEREE_REVIEW\"}";auto z=req(a,RefereeAuthorityOperation::FinalDeclare,f,"f");e(a.finalDeclare(z,c,2).ok&&a.state().reviewNeeded,"final");e(a.consume("shot",3)&&!a.consume("other",4),"consume once");e(a.finalDeclare(z,c,4).ok&&a.state().phase==PushReviewPhase::Consumed,"retry");}void bad(){Auth x;PushReviewAuthority a(&x);a.reset("r");PushReviewContext c{0,1,"s"};for(auto p:{"{\"push\":true}","{\"foul\":true}","{\"contact_duration\":1}","{\"distance_threshold\":1}"}){auto r=req(a,RefereeAuthorityOperation::Propose,p,p);e(!a.propose(r,c,1).ok,"bad payload");}}}int main(){test();bad();std::cout<<"push_review_declaration_tests: PASS\n";}
